{
  "name": "@cyan_tachyon/inf-copilot",
  "version": "1.0.0",
  "description": "OpenCode plugin that forces X-Initiator header to 'agent' for all GitHub Copilot requests",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "type": "module",
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "npm run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "typescript": "^5.8.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "copilot",
    "github-copilot",
    "x-initiator"
  ],
  "publishConfig": {
    "access": "public"
  },
  "license": "MIT"
}
